package com.hssa.auth.entity; import jakarta.persistence.*; import lombok.AllArgsConstructor; import lombok.Getter; import lombok.NoArgsConstructor; import lombok.Setter; import org.hibernate.annotations.CreationTimestamp; import java.time.LocalDateTime; import java.util.UUID; @Entity @Table(name = "user_sessions", schema = "auth") @Getter @Setter @NoArgsConstructor @AllArgsConstructor public class UserSession { @Id @GeneratedValue(strategy = GenerationType.UUID) @Column(name = "id", updatable = false, nullable = false) private UUID id; @ManyToOne(fetch = FetchType.LAZY) @JoinColumn(name = "user_id", nullable = false) private User user; @ManyToOne(fetch = FetchType.LAZY) @JoinColumn(name = "refresh_token_id") private RefreshToken refreshToken; @Column(name = "session_token", nullable = false, unique = true) private String sessionToken; @Column(name = "ip_address") private String ipAddress; @Column(name = "user_agent", columnDefinition = "TEXT") private String userAgent; @Column(name = "browser", length = 100) private String browser; @Column(name = "browser_version", length = 100) private String browserVersion; @Column(name = "operating_system", length = 100) private String operatingSystem; @Column(name = "device_type", length = 100) private String deviceType; @Column(name = "device_name", length = 200) private String deviceName; @Column(name = "login_at", nullable = false) private LocalDateTime loginAt = LocalDateTime.now(); @Column(name = "last_activity_at", nullable = false) private LocalDateTime lastActivityAt = LocalDateTime.now(); @Column(name = "expires_at", nullable = false) private LocalDateTime expiresAt; @Column(name = "logout_at") private LocalDateTime logoutAt; @Column(name = "is_active", nullable = false) private boolean isActive = true; @CreationTimestamp @Column(name = "created_at", nullable = false, updatable = false) private LocalDateTime createdAt; }
